func (stager *Stager) enforceSemantic() (needCommit bool) {
	propagateCrossStageBranches(stager.stage)
	enforceInstanceNames(stager.stage)
	stager.semanticErrors = ValidateXSDConstraints(stager.stage)

	if stager.probeForm != nil {
		stager.probeForm.ResetNotifications()
		for _, errMsg := range stager.semanticErrors {
			stager.probeForm.AddNotification(time.Now(), errMsg)
		}
		stager.probeForm.CommitNotificationTable()
	}
	return false
}

